import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    urls = re.findall(r'https?://[^\s]+', myString)
    domains = [urllib.parse.urlparse(url).netloc for url in urls]
    geolocation_data = {}
    for domain in domains:
        try:
            response = requests.get(f'https://ipapi.co/{domain}/json/', headers={'Authorization': f'Bearer {API_KEY}'})
            if response.status_code == 200:
                geolocation_data[domain] = response.json()
            else:
                geolocation_data[domain] = None
        except:
            geolocation_data[domain] = None
    return geolocation_data
